package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.io.*;import java.util.*;
/** On-device learning of the reader from saved documents: literal sentences of the source are the only labels.
 *  A candidate is published only if it reads held-out formulations of the same block better and keeps its fixed controls. */
final class LectorTraining{
 static final java.util.concurrent.locks.ReentrantLock TRAIN=new java.util.concurrent.locks.ReentrantLock();
 static final float RATE=.02f;static final double RADIUS=.6,CONTROL_SLACK=.03;static final int EPOCHS=2,MAX_LAYERS=10;
 static final long[] GROW_AT={150000L,600000L};static final int BASE_LAYERS=6,CHARGING_PASSES=8;
 static final String[][] CONTROLS={
  {"La brumelia es una planta ficticia de hojas azules. Crece en valles húmedos del norte. Sus semillas se usan para teñir telas.","que es la brumelia","La brumelia es una planta ficticia de hojas azules."},
  {"El puente Aldar une dos barrios de la ciudad. Fue inaugurado en 1954 por el ingeniero Tomás Rivel. Mide ciento veinte metros de largo.","hablame de tomás rivel","Fue inaugurado en 1954 por el ingeniero Tomás Rivel."},
  {"Los corales viven en aguas cálidas y poco profundas. Se alimentan de plancton que atrapan con sus tentáculos. Muchos forman arrecifes.","que dice sobre plancton","Se alimentan de plancton que atrapan con sus tentáculos."},
  {"La imprenta permitió copiar libros con rapidez. Antes los textos se escribían a mano. Su difusión cambió la educación en Europa.","que es un velocirraptor","no encontre ese dato en el fragmento ."}};
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-reader-training",0);}
 static JSONObject state(Context c)throws Exception{JSONObject s=new JSONObject(prefs(c).getString("state","{}"));if(!s.has("cursors"))s.put("cursors",new JSONObject());for(String k:new String[]{"accepted","rejected","tokens","grown"})if(!s.has(k))s.put(k,0);return s;}
 static void save(Context c,JSONObject s)throws Exception{if(!prefs(c).edit().putString("state",s.toString()).commit())throw new IOException("No pude guardar el progreso del lector");}
 static void forget(Context c)throws Exception{JSONObject s=state(c);s.put("cursors",new JSONObject());save(c,s);}

 static TransformerTraining.Sequence grounded(BananaTransformer m,String fragment,String question,String answer){int[] prompt=Lector.prompt(m,fragment,question);List<Integer> a=m.encode(answer,Lector.ANSWER_TOKENS+1);if(prompt==null||a.isEmpty()||a.size()>Lector.ANSWER_TOKENS||prompt.length+a.size()+1>m.context)return null;int[] input=new int[prompt.length+a.size()],labels=new int[input.length];Arrays.fill(labels,-1);System.arraycopy(prompt,0,input,0,prompt.length);int start=prompt.length-1;for(int i=0;i<a.size();i++){input[prompt.length+i]=a.get(i);labels[start+i]=a.get(i);}labels[labels.length-1]=5;return new TransformerTraining.Sequence(input,labels);}
 static TransformerTraining.Sequence language(BananaTransformer m,String text){List<Integer> tokens=m.encode(text,200);if(tokens.size()<16)return null;return ReadingWeights.language(tokens,0,tokens.size());}
 /** Longest word that appears in this sentence and in no other sentence of the fragment. */
 static String keyTerm(String sentence,List<String> all){String best=null;StringBuilder rest=new StringBuilder(" ");for(String o:all)if(o!=sentence)rest.append(ChatLanguage.normalize(o)).append(' ');String others=rest.toString();java.util.regex.Matcher w=java.util.regex.Pattern.compile("[\\p{L}]{6,}").matcher(sentence);while(w.find()){String word=w.group();if(others.contains(" "+ChatLanguage.normalize(word)+" "))continue;if(best==null||word.length()>best.length())best=word;}return best;}
 static final class Batch{final List<TransformerTraining.Sequence> train=new ArrayList<>(),eval=new ArrayList<>();/** fragment, held-out question, literal sentence */final List<String[]> probes=new ArrayList<>();int definitions,mentions,labels;}
 /** Examples of one fragment: «que es X»/«que dice sobre X» to train, another wording of each to evaluate, plus plain continuation. */
 static Batch batch(BananaTransformer m,String fragment,String absentTerm)throws Exception{return batch(m,null,fragment,absentTerm);}
 static Batch batch(BananaTransformer m,String title,String text,String absentTerm)throws Exception{Batch b=new Batch();final String source=text,fragment=Lector.context(m,title,text);List<String> sentences=new ArrayList<>(Arrays.asList(KnowledgeNotebook.chunks(source)));Set<String> used=new HashSet<>();
  JSONArray rows=new JSONArray().put(new JSONObject().put("id","x").put("text",source));
  for(ReadingKnowledge.Definition d:ReadingKnowledge.definitions(rows)){if(b.definitions>=2||!source.contains(d.sentence))continue;TransformerTraining.Sequence t=grounded(m,fragment,"que es "+d.term.toLowerCase(Locale.ROOT),d.sentence),e=grounded(m,fragment,"que significa "+d.term.toLowerCase(Locale.ROOT),d.sentence);if(t!=null&&e!=null&&used.add(d.sentence)){b.train.add(t);b.eval.add(e);b.probes.add(new String[]{fragment,"que significa "+d.term.toLowerCase(Locale.ROOT),d.sentence});b.definitions++;}}
  int step=Math.max(1,sentences.size()/3);for(int i=0;i<sentences.size()&&b.mentions<3;i+=step){String s=sentences.get(i);if(s.length()<25||used.contains(s)||!source.contains(s))continue;String k=keyTerm(s,sentences);if(k==null)continue;k=k.toLowerCase(Locale.ROOT);TransformerTraining.Sequence t=grounded(m,fragment,"que dice sobre "+k,s),e=grounded(m,fragment,"hablame de "+k,s);if(t!=null&&e!=null&&used.add(s)){b.train.add(t);b.eval.add(e);b.probes.add(new String[]{fragment,"hablame de "+k,s});b.mentions++;}}
  if(absentTerm!=null&&!ChatLanguage.normalize(fragment).contains(ChatLanguage.normalize(absentTerm))){TransformerTraining.Sequence n=grounded(m,fragment,"que es "+absentTerm.toLowerCase(Locale.ROOT),Lector.NEGATIVE);if(n!=null&&!b.train.isEmpty())b.train.add(n);}
  TransformerTraining.Sequence plain=language(m,source);if(plain!=null&&!b.train.isEmpty())b.train.add(plain);for(TransformerTraining.Sequence s:b.train)for(int l:s.labels)if(l>=0)b.labels++;return b;}
 static List<TransformerTraining.Sequence> controls(BananaTransformer m){List<TransformerTraining.Sequence> out=new ArrayList<>();for(String[] row:CONTROLS){TransformerTraining.Sequence s=grounded(m,row[0],row[1],row[2]);if(s!=null)out.add(s);}return out;}
 static int first(int[] labels){for(int i=0;i<labels.length;i++)if(labels[i]>=0)return i;return labels.length;}
 static double loss(BananaTransformer m,List<TransformerTraining.Sequence> rows,ReadingWeights.Governor governor)throws Exception{double total=0;for(TransformerTraining.Sequence s:rows){BananaTransformer.Session session=m.session();int from=first(s.labels);double nll=0;int n=0;for(int i=0;i<s.input.length;i++){if((i&7)==0&&governor!=null)governor.check();if(i<from){session.advance(s.input[i]);continue;}float[] p=HeadTrainer.probabilities(session.step(s.input[i]));if(s.labels[i]>=0){nll-=Math.log(Math.max(1e-12,p[s.labels[i]]));n++;}}total+=nll/Math.max(1,n);}return total/Math.max(1,rows.size());}
 static void step(BananaTransformer m,TransformerTraining.Sequence s,float rate){int from=first(s.labels);TransformerTraining.Tape tape=new TransformerTraining.Tape();TransformerTraining.Tensor logits=TransformerTraining.forwardTail(m,tape,s.input,from);TransformerTraining.loss(logits,Arrays.copyOfRange(s.labels,from,s.labels.length),true);tape.backward();tape.update(rate);}
 /** Trains the given model in place; restores it when the candidate is rejected or interrupted. */
 static JSONObject fit(BananaTransformer m,Batch b,ReadingWeights.Governor governor)throws Exception{if(b.train.isEmpty()||b.eval.isEmpty())throw new IllegalArgumentException("Sin ejemplos suficientes del fragmento");List<TransformerTraining.Sequence> controls=controls(m);float[][] snapshot=TransformerTraining.snapshot(m);boolean accepted=false;
  try{double before=loss(m,b.eval,governor),controlBefore=loss(m,controls,governor);
   for(int epoch=0;epoch<EPOCHS;epoch++)for(TransformerTraining.Sequence s:b.train){governor.check();step(m,s,RATE);TransformerTraining.project(m,snapshot,RADIUS);}
   double after=loss(m,b.eval,governor),controlAfter=loss(m,controls,governor),delta=TransformerTraining.distance(m,snapshot);accepted=!Double.isNaN(after)&&!Double.isInfinite(after)&&after<before-1e-4&&controlAfter<=controlBefore+CONTROL_SLACK&&delta>0;
   return new JSONObject().put("kind","reader").put("method","SGD completo del lector con oraciones literales del fragmento").put("accepted",accepted).put("before",before).put("after",after).put("controlBefore",controlBefore).put("controlAfter",controlAfter).put("weightDeltaL2",delta).put("epochs",EPOCHS).put("trainSequences",b.train.size()).put("evalSequences",b.eval.size()).put("definitionPairs",b.definitions).put("mentionPairs",b.mentions).put("labelTokens",b.labels).put("parameters",m.parameters()).put("layers",m.layers).put("metric","NLL de otra formulación de las mismas oraciones del fragmento; no es un benchmark externo");
  }finally{if(!accepted)ReadingWeights.restore(m,snapshot);}}

 /** A copy of the model with one more block whose output projections are zero: it computes exactly the same until trained. */
 static BananaTransformer grow(BananaTransformer m)throws Exception{if(m.layers>=MAX_LAYERS)throw new IOException("El lector ya tiene el máximo de "+MAX_LAYERS+" capas");ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(0x42544631);for(int n:new int[]{m.vocabSize,m.d,m.heads,m.layers+1,m.context,m.ff})out.writeInt(n);BananaTransformer.write(out,m.embedding);BananaTransformer.write(out,m.position);
  for(BananaTransformer.Block b:m.blocks){BananaTransformer.write(out,b.n1w);BananaTransformer.write(out,b.n1b);BananaTransformer.write(out,b.qkv);BananaTransformer.write(out,b.qkvb);BananaTransformer.write(out,b.o);BananaTransformer.write(out,b.ob);BananaTransformer.write(out,b.n2w);BananaTransformer.write(out,b.n2b);BananaTransformer.write(out,b.f1);BananaTransformer.write(out,b.f1b);BananaTransformer.write(out,b.f2);BananaTransformer.write(out,b.f2b);}
  Random random=new Random(7919L*(m.layers+1));float[] ones=new float[m.d];Arrays.fill(ones,1f);BananaTransformer.write(out,ones);BananaTransformer.write(out,new float[m.d]);BananaTransformer.write(out,noise(random,m.d,3*m.d));BananaTransformer.write(out,new float[3*m.d]);BananaTransformer.write(out,new float[m.d][m.d]);BananaTransformer.write(out,new float[m.d]);BananaTransformer.write(out,ones);BananaTransformer.write(out,new float[m.d]);BananaTransformer.write(out,noise(random,m.d,m.ff));BananaTransformer.write(out,new float[m.ff]);BananaTransformer.write(out,new float[m.ff][m.d]);BananaTransformer.write(out,new float[m.d]);
  BananaTransformer.write(out,m.normWeight);BananaTransformer.write(out,m.normBias);BananaTransformer.write(out,m.head);BananaTransformer.write(out,m.headBias);out.flush();StringBuilder words=new StringBuilder();for(String w:m.vocab)words.append(w).append('\n');
  return new BananaTransformer(new ByteArrayInputStream(bytes.toByteArray()),new ByteArrayInputStream(words.toString().getBytes("UTF-8")),new ByteArrayInputStream(m.tokenizerJson.getBytes("UTF-8")));}
 static float[][] noise(Random r,int rows,int cols){float[][] a=new float[rows][cols];for(float[] row:a)for(int j=0;j<cols;j++)row[j]=(float)(r.nextGaussian()*.02);return a;}

 /** Next unread block (document, ordinal) of the library, or null. */
 /** One block in five is never trained: it is the exam the reader has not seen. */
 static boolean reserved(int ordinal){return ordinal%5==4;}
 /** The user's own corrections and contributions are studied before web pages. */
 static List<NotebookDisk.Doc> ordered(NotebookDisk disk)throws Exception{List<NotebookDisk.Doc> all=disk.index.list(NotebookDisk.MAX_DOCUMENTS),out=new ArrayList<>();for(NotebookDisk.Doc d:all)if(d.title.equals("Corrección del usuario"))out.add(d);for(NotebookDisk.Doc d:all)if(d.origin.equals("user")&&!d.title.equals("Corrección del usuario"))out.add(d);for(NotebookDisk.Doc d:all)if(!d.origin.equals("user"))out.add(d);return out;}
 /** Starts another pass over the library; only offered while charging, a bounded number of times per day. */
 static boolean repass(JSONObject state,long now,boolean charging,int limit)throws Exception{long day=now/LearningPlan.DAY_MS;if(state.optLong("passDay",-1)!=day)state.put("passDay",day).put("passes",0);if(!charging||state.getInt("passes")>=limit)return false;JSONObject cursors=state.getJSONObject("cursors");boolean any=false;for(Iterator<String> it=cursors.keys();it.hasNext();){JSONObject cur=cursors.getJSONObject(it.next());if(cur.optBoolean("done")){cur.put("done",false).put("ordinal",0);any=true;}}if(any)state.put("passes",state.getInt("passes")+1);return any;}
 static NotebookDisk.Hit next(NotebookDisk disk,JSONObject state)throws Exception{JSONObject cursors=state.getJSONObject("cursors");JSONArray review=state.optJSONArray("review");while(review!=null&&review.length()>0){JSONObject r=review.getJSONObject(0);review.remove(0);NotebookDisk.Doc d=disk.index.get(r.getString("id"));if(d==null||!d.sha.equals(r.optString("sha")))continue;List<NotebookDisk.Hit> hits=disk.index.slice(d.id,r.getInt("ordinal"),1);if(!hits.isEmpty()){state.put("reviewing",true);return hits.get(0);}}state.put("reviewing",false);for(NotebookDisk.Doc d:ordered(disk)){JSONObject cur=cursors.optJSONObject(d.id);if(cur==null||!cur.optString("sha").equals(d.sha)){cur=new JSONObject().put("sha",d.sha).put("ordinal",0).put("done",false);cursors.put(d.id,cur);}if(cur.getBoolean("done"))continue;while(true){List<NotebookDisk.Hit> hits=disk.index.slice(d.id,cur.getInt("ordinal"),1);if(hits.isEmpty()){cur.put("done",true);break;}if(!reserved(hits.get(0).ordinal))return hits.get(0);cur.put("ordinal",hits.get(0).ordinal+1);}}return null;}
 static void advance(JSONObject state,NotebookDisk.Hit hit)throws Exception{if(state.optBoolean("reviewing"))return;JSONObject cur=state.getJSONObject("cursors").getJSONObject(hit.doc.id);if(cur.getInt("ordinal")<=hit.ordinal)cur.put("ordinal",hit.ordinal+1);}
 /** One block: build examples from its best-fitting piece, train, and report. The model is changed only when accepted. */
 static JSONObject block(BananaTransformer m,NotebookDisk.Hit hit,ReadingWeights.Governor governor)throws Exception{List<String> windows=Lector.windows(m,hit.text,new HashSet<String>(),2);JSONObject skipped=new JSONObject().put("kind","reader").put("accepted",false).put("skipped",true).put("sourceId",hit.doc.id).put("source",hit.doc.source).put("ordinal",hit.ordinal);if(windows.isEmpty())return skipped;String absent=windows.size()>1?keyTerm(windows.get(1),Arrays.asList(windows.get(1))):null;Batch b=batch(m,hit.doc.title,windows.get(0),absent);if(b.train.isEmpty()||b.eval.isEmpty())return skipped;return fit(m,b,governor).put("sourceId",hit.doc.id).put("sourceSha256",hit.doc.sha).put("source",hit.doc.source).put("ordinal",hit.ordinal);}

 static void prune(Context c)throws Exception{Set<String> keep=new HashSet<>();for(String key:new String[]{"reader","readerBackup"}){String raw=ModelDepot.prefs(c).getString(key,"");if(!raw.isEmpty())keep.add(new File(new JSONObject(raw).optString("path")).getName());}File[] files=c.getDir("model-training",0).listFiles();if(files==null)return;String champion=state(c).optJSONObject("champion")==null?"":new File(state(c).getJSONObject("champion").optString("path")).getName();for(File f:files)if(f.getName().startsWith("reader-reading-")&&!keep.contains(f.getName())&&!f.getName().equals(champion))f.delete();}
 static void publish(Context c,BananaTransformer m,JSONObject report,String revision)throws Exception{File checkpoint=ModelDepot.save(c,"reader-reading",m.container());boolean ok=false;try{try(InputStream in=new FileInputStream(checkpoint)){BananaTransformer reopened=BananaTransformer.container(in);if(reopened.parameters()!=m.parameters())throw new IOException("El checkpoint del lector no se reprodujo");}ModelDepot.publish(c,"reader",checkpoint,report,revision);ok=true;Lector.forget();}finally{if(!ok)checkpoint.delete();}prune(c);}
 /** One background step. Returns false when there is nothing to read or the reader is unavailable. */
 static boolean cycle(Context c,boolean background)throws Exception{if(c instanceof NotebookDisk.Provider)return false;if(!TRAIN.tryLock())return false;try{NotebookDisk disk=NotebookDisk.of(c);JSONObject state=state(c);NotebookDisk.Hit hit=next(disk,state);if(hit==null&&repass(state,System.currentTimeMillis(),LectorExam.charging(c)&&LearningLoop.visible==0,CHARGING_PASSES))hit=next(disk,state);if(hit==null){save(c,state);return LectorExam.due(c,state)&&LectorExam.background(c);}String revision=ModelDepot.revision(c,"reader");BananaTransformer m=Lector.copy(c);ReadingBudget governor=new ReadingBudget(c,360,background);JSONObject report=block(m,hit,governor);advance(state,hit);
   if(report.optBoolean("accepted")){publish(c,m,report,revision);state.put("accepted",state.getInt("accepted")+1).put("tokens",state.getLong("tokens")+report.getInt("labelTokens"));int grown=state.getInt("grown");if(grown<GROW_AT.length&&state.getLong("tokens")>=GROW_AT[grown]&&m.layers<MAX_LAYERS){String next=ModelDepot.revision(c,"reader");BananaTransformer bigger=grow(m);publish(c,bigger,new JSONObject(report.toString()).put("growth",true).put("layers",bigger.layers).put("parameters",bigger.parameters()),next);state.put("grown",grown+1);}}
   else if(!report.optBoolean("skipped"))state.put("rejected",state.getInt("rejected")+1);
   state.put("last",report).put("sinceExam",state.optInt("sinceExam")+1);save(c,state);if(LectorExam.due(c,state))try{LectorExam.background(c);}catch(ReadingBudget.Paused later){}return true;}finally{TRAIN.unlock();}}
 static String growNow(Context c)throws Exception{if(!TRAIN.tryLock())return "El lector está entrenando ahora; probá de nuevo en un momento.";try{String revision=ModelDepot.revision(c,"reader");BananaTransformer m=Lector.copy(c);long before=m.parameters();BananaTransformer bigger=grow(m);ReadingBudget governor=new ReadingBudget(c,180);double a=loss(m,controls(m),governor),b=loss(bigger,controls(bigger),governor);if(Math.abs(a-b)>1e-4)throw new IOException("La capa nueva cambió las respuestas de control; no la activé");publish(c,bigger,new JSONObject().put("kind","reader").put("accepted",true).put("growth",true).put("manual",true).put("layers",bigger.layers).put("parameters",bigger.parameters()).put("controlBefore",a).put("controlAfter",b),revision);return "Agregué una capa al lector: de "+m.layers+" a "+bigger.layers+" capas y de "+before+" a "+bigger.parameters()+" parámetros. La capa nueva empieza sin efecto (las respuestas de control dieron igual) y se irá ajustando con el entrenamiento de tus lecturas. Cada capa hace más lenta la lectura y el entrenamiento.";}finally{TRAIN.unlock();}}
 static String summary(Context c)throws Exception{JSONObject s=state(c);JSONObject cursors=s.getJSONObject("cursors");int done=0,docs=0;for(Iterator<String> it=cursors.keys();it.hasNext();){docs++;if(cursors.getJSONObject(it.next()).optBoolean("done"))done++;}StringBuilder out=new StringBuilder(Lector.card(c)).append("\nBloques de tus lecturas aceptados: ").append(s.getInt("accepted")).append(" · rechazados: ").append(s.getInt("rejected")).append(" · tokens de respuesta entrenados: ").append(s.getLong("tokens")).append("\nDocumentos recorridos por completo: ").append(done).append(" de ").append(docs).append(" vistos.");JSONObject last=s.optJSONObject("last");if(last!=null&&last.has("before"))out.append("\nÚltimo bloque: pérdida ").append(String.format(Locale.ROOT,"%.3f",last.getDouble("before"))).append(" → ").append(String.format(Locale.ROOT,"%.3f",last.getDouble("after"))).append(last.getBoolean("accepted")?" (aceptado)":" (rechazado, se conservó el modelo anterior)");
  int grown=s.getInt("grown");if(grown<GROW_AT.length)out.append("\nPróxima capa automática al llegar a ").append(GROW_AT[grown]).append(" tokens entrenados.");out.append(LectorExam.history(s));return out.append("\nEl lector sólo copia oraciones de los fragmentos guardados; una pérdida menor no demuestra comprensión general.").toString();}
}
